import assert from 'node:assert/strict';
import {tierFor} from './objective-market-promotion.mjs';
const q=(sources,ev)=>tierFor({sources,ev,fresh:true,exact:true});
assert.equal(q(2,0.05),'SCREENING','two independent outside sources must not reach WATCH');
assert.equal(q(3,0.05),'WATCH','three independent outside sources are WATCH only');
assert.equal(q(4,0.05),'WATCH','four outside sources are WATCH only');
assert.equal(q(5,0.03),'ACTION','five sources and verified EV can reach ACTION');
assert.equal(q(2,0.005),'SCREENING','two sources remain SCREENING at positive EV');
assert.equal(q(3,0.005),'SCREENING','three sources with low EV do not meet WATCH');
assert.equal(q(4,0.015),'WATCH','four sources with >=1% EV reach WATCH');
console.log('OBJECTIVE_SOURCE_TIER_GATES_VERIFIED');
import {mergeObjectiveRowsIntoBoard} from './objective-market-board-merge.mjs';
const id={sport:'dota2',match:'Aurora Gaming vs LGD Gaming',market:'Map 1 Team Kills',marketKey:'team_kills',target:'Aurora Gaming',line:25.5,scope:{map:1},side:'over',state:'prematch',settlementScope:'standard',tier:'SCREENING',thunderpick:2.05};
const lowDepth={...id,independentSources:1,estimatedEV:0.32,outside:[{sourceFamily:'ggbet',price:1.67}]};
const highDepth={...id,independentSources:2,estimatedEV:0.08,outside:[{sourceFamily:'ggbet',price:1.67},{sourceFamily:'stake-oddin',price:1.81}]};
const merged=mergeObjectiveRowsIntoBoard({board:{rows:[highDepth],coverageAudit:{dota2:{}}},objectiveRows:[lowDepth]});
assert.equal(merged.rows.length,1,'same exact contract should merge once');
assert.equal(merged.rows[0].independentSources,2,'verified two-source quote must take priority over unsupported one-source EV');
console.log('OBJECTIVE_SOURCE_DEPTH_MERGE_VERIFIED');
